-- 크기마다 문장이 다르다

@Test
void in_크기() {
    Set<String> shapes = new LinkedHashSet<>();
    for (int n = 1; n <= 4; n++) {
        em.clear();
        List<String> names = IntStream.rangeClosed(1, n)
                .mapToObj(i -> "m" + i).toList();
        shapes.add(sqlCapture.capture(() ->
                queryFactory.selectFrom(member)
                        .where(member.username.in(names)).fetch()));
    }
    System.out.println("서로 다른 문장: " + shapes.size());
}

