-- like 넷

@Test
void like_넷() {
    for (String kind : List.of("like", "startsWith", "contains", "endsWith")) {
        em.clear();
        System.out.println("--- " + kind + " ---");
        BooleanExpression cond = switch (kind) {
            case "like"       -> member.username.like("m%");
            case "startsWith" -> member.username.startsWith("m");
            case "contains"   -> member.username.contains("m");
            default           -> member.username.endsWith("1");
        };
        queryFactory.selectFrom(member).where(cond).fetch();
    }
}

